<?php
require_once __DIR__ . '/../includes/auth.php'; require_login(); update_overdue_appointments(); $active_menu='reports';
$date=trim((string)($_GET['date']??''));$status=trim((string)($_GET['status']??''));$where=[];$params=[];if(is_valid_date($date)){$where[]='a.appointment_date=:date';$params[':date']=$date;}if(in_array($status,['Scheduled','Completed','Cancelled','No-show'],true)){$where[]='a.status=:status';$params[':status']=$status;}$sql="SELECT a.*,CONCAT(c.first_name,' ',c.last_name) customer_name,s.service_name,CONCAT(st.first_name,' ',st.last_name) staff_name FROM appointments a JOIN customers c ON c.customer_id=a.customer_id JOIN services s ON s.service_id=a.service_id JOIN staff st ON st.staff_id=a.staff_id";if($where)$sql.=' WHERE '.implode(' AND ',$where);$rows=all_rows($sql.' ORDER BY a.appointment_date DESC,a.appointment_time DESC',$params);$page_title='Appointment Report';require __DIR__.'/../includes/header.php';
?>
<h2 class="print-heading">Appointment Report</h2><?php require __DIR__.'/../includes/report_nav.php';?><form method="get" class="row g-2 align-items-end no-print mb-3"><div class="col-sm-4"><label class="form-label">Appointment date</label><input class="form-control" type="date" name="date" value="<?=e($date)?>"></div><div class="col-sm-4"><label class="form-label">Status</label><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['Scheduled','Completed','Cancelled','No-show'] as $item):?><option <?= $status===$item?'selected':''?>><?=e($item)?></option><?php endforeach;?></select></div><div class="col-sm-4"><button class="btn btn-primary">Apply filters</button> <a class="btn btn-outline-secondary" href="<?=e(app_url('reports/appointments.php'))?>">Clear</a></div></form><div class="card shadow-sm table-card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Appointment ID</th><th>Customer</th><th>Service</th><th>Staff</th><th>Date</th><th>Time</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="text-center py-4 text-secondary">No appointments match the selected filters.</td></tr><?php endif;?><?php foreach($rows as $row):?><tr><td>#<?= (int)$row['appointment_id']?></td><td><?=e($row['customer_name'])?></td><td><?=e($row['service_name'])?></td><td><?=e($row['staff_name'])?></td><td><?=e($row['appointment_date'])?></td><td><?=e(date('H:i',strtotime($row['appointment_time'])))?></td><td><?=status_badge($row['status'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';
